        frontier = [(heuristic(start, goal), 0, start)]
        came_from = {}
        cost_so_far = {start: 0}
        visited = set()
        while frontier:
            _, cost, current = heapq.heappop(frontier)
            if current in visited:
                continue
            visited.add(current)
